INSERT INTO meetings (meeting_id, project_id, title, meeting_date, kind, status, summary, visibility) VALUES ('mtg-2026-08-13-platform', 'proj-platform', 'Platform weekly', '2026-08-13'::date, 'sync', 'held', 'Unfroze orders schema. Auth0 decision reversed in favor of in-house identity.', 'team');
