INSERT INTO meetings (meeting_id, project_id, title, meeting_date, kind, status, summary, visibility) VALUES ('mtg-2026-09-04-platform', 'proj-platform', 'Platform weekly', '2026-09-04'::date, 'sync', 'held', 'Runbook incomplete, dual-write lag, unsigned SLA. These three items block Mobile.', 'team');
INSERT INTO meetings (meeting_id, project_id, title, meeting_date, kind, status, summary, visibility) VALUES ('mtg-2026-07-08-mobile', 'proj-mobile', 'Mobile weekly', '2026-07-08'::date, 'sync', 'held', 'Team decided to delay the mobile launch to November to wait on platform.', 'team');
